python
def roundDeskPositiveInkInvoice(readings, k):
    a=readings
    out=[]
    from collections import deque
    remaining=a[:]
    queue=deque(i for i,x in enumerate(a) if x>0)
    out=[0]*len(a)
    time=0
    while queue:
        i=queue.popleft()
        served=min(k,remaining[i])
        remaining[i]-=served
        time+=served
        if remaining[i]: queue.append(i)
        else: out[i]=time
    return sum(x for x in out if x>0)


java
class Solution {
  public int roundDeskPositiveInkInvoice(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {int[]remaining=a.clone(),done=new int[a.length];Deque<Integer>queue=new ArrayDeque<>();for(int i=0;i<a.length;i++)if(a[i]>0)queue.add(i);int time=0;while(!queue.isEmpty()){int i=queue.remove(),served=Math.min(k,remaining[i]);remaining[i]-=served;time+=served;if(remaining[i]>0)queue.add(i);else done[i]=time;}for(int x:done)out.add(x);}
    int answer=0;for(int x:out)if(x>0)answer+=x;return answer;
  }
}
